package com.example.demo;

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;

@Configuration
public class GreetingStyles {
    @Bean
    @Primary
    public GreetingStyle casualStyle() {
        return name -> "Hello, " + name;
    }

    @Bean
    @Qualifier("formal")
    public GreetingStyle formalStyle() {
        return name -> "Good day, " + name;
    }
}

package com.example.demo;

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Component;

@Component
public class StyleDemo {
    private final GreetingStyle defaultStyle;
    private final GreetingStyle explicitStyle;

    public StyleDemo(
            GreetingStyle defaultStyle,
            @Qualifier("formal") GreetingStyle explicitStyle) {
        this.defaultStyle = defaultStyle;
        this.explicitStyle = explicitStyle;
    }

    public String defaultGreeting(String name) {
        return defaultStyle.greet(name);
    }

    public String formalGreeting(String name) {
        return explicitStyle.greet(name);
    }
}

